#include <stdio.h>

// Point라는 설계도 작성
struct Point {
    int x;
    int y;
};

int main() {
    // 객체(구조체 변수) 생성
    struct Point p1 = {10, 20};

    // 멤버 접근 (.)
    printf("p1: (%d, %d)\n", p1.x, p1.y);

    // 대입 연산
    struct Point p2 = p1; // 전체 복사!
    p2.x = 99;

    printf("p1: (%d, %d)\n", p1.x, p1.y);
    printf("p2: (%d, %d)\n", p2.x, p2.y);

    return 0;
}
